private void generateSamplePdf(String fileName, String text) throws FileNotFoundException, DocumentException {
    if (!fileName.endsWith(".pdf")) {
        fileName += ".pdf";
    }
    String storagePath = System.getenv("PDF_STORAGE_PATH");
    if (storagePath == null || storagePath.isEmpty()) {
        storagePath = System.getProperty("user.dir");
    }
    java.io.File storageDir = new java.io.File(storagePath);
    if (!storageDir.exists()) {
        storageDir.mkdirs();
    }
    Document document = new Document();
    PdfWriter.getInstance(document, new FileOutputStream(new java.io.File(storageDir, fileName)));
    document.open();
    Paragraph paragraph = new Paragraph(text);
    document.add(paragraph);
    document.close();
}

